/* @lc app=leetcode id=2478 lang=kotlin */ class Solution { fun beautifulPartitions(s: String, k: Int, minL: Int): Int = s.length.let { n -> "2357".let { p -> if (minL * k > n || s[0] !in p || s[n - 1] in p) 0 else (minL..n - minL).filter { s[it] in p && s[it - 1] !in p }.let { b -> if (k == 1) 1 else (1 until k - 1).fold(LongArray(b.size) { 1L }) { dp, _ -> LongArray(b.size).let { next -> b.indices.fold(0 to 0L) { (j, ss), i -> (generateSequence(j) { it + 1 }.takeWhile { it < b.size && b[i] - b[it] >= minL }.fold(j to ss) { (cJ, cS), idx -> (idx + 1) to (cS + dp[idx]) % 1000000007 }).also { next[i] = it.second } }.let { next } } }.let { res -> (res.sum() % 1000000007).toInt() } } } } }